<section class="page-header"><div><span class="eyebrow"><?= count($rows) ?> active profiles</span><h1>Staff Directory</h1><p>Employees, roles, departments and secure portal access.</p></div><div class="page-actions"><?php if(can('staff.create')):?><a class="button button-primary" href="<?= url('staff/create') ?>"><i class="fa-solid fa-user-plus"></i> Add staff member</a><?php endif;?></div></section>
<section class="panel table-panel"><form class="filter-bar" method="get"><div class="search-control"><i class="fa-solid fa-magnifying-glass"></i><input name="q" value="<?= e($q) ?>" placeholder="Search staff name, email or code…"></div><button class="button button-secondary">Search</button></form><div class="staff-grid"><?php foreach($rows as $row):?><article class="staff-card"><div class="staff-card-head"><span class="avatar avatar-lg"><?= e(mb_substr($row['name'],0,1)) ?></span><div><h3><?= e($row['name']) ?></h3><p><?= e($row['designation_name']?:'Staff member') ?></p></div><span class="status-badge <?= status_class($row['employment_status']) ?>"><?= e(ucfirst($row['employment_status'])) ?></span></div><dl><div><dt>Employee code</dt><dd><?= e($row['employee_code']) ?></dd></div><div><dt>Department</dt><dd><?= e($row['department_name']?:'—') ?></dd></div><div><dt>Email</dt><dd><?= e($row['email']) ?></dd></div><div><dt>Joined</dt><dd><?= e(date('d M Y',strtotime($row['joining_date']))) ?></dd></div></dl><div class="staff-card-actions"><a href="mailto:<?= e($row['email']) ?>" class="button button-secondary button-sm"><i class="fa-regular fa-envelope"></i> Email</a><?php if(can('staff.edit')):?><a href="<?= url('staff/'.$row['id'].'/edit') ?>" class="button button-ghost button-sm"><i class="fa-regular fa-pen-to-square"></i> Edit</a><?php endif;?></div></article><?php endforeach;?><?php if(!$rows):?><div class="empty-state"><span><i class="fa-solid fa-users"></i></span><h3>No staff found</h3><p>Try a different search or add the first staff member.</p></div><?php endif;?></div></section>
